import {LightningElement} from 'lwc'; import {REFRESH_COMPLETE,REFRESH_ERROR,REFRESH_COMPLETE_WITH_ERROR,REFRESH_COMPLETE_WITH_ERRORS} from 'lightning/refresh';export default class Probe extends LightningElement {result='pending';connectedCallback(){this.result=JSON.stringify({complete:{type:typeof REFRESH_COMPLETE,value:REFRESH_COMPLETE},error:{type:typeof REFRESH_ERROR,value:REFRESH_ERROR},singular:{type:typeof REFRESH_COMPLETE_WITH_ERROR,value:REFRESH_COMPLETE_WITH_ERROR},plural:{type:typeof REFRESH_COMPLETE_WITH_ERRORS,value:REFRESH_COMPLETE_WITH_ERRORS}})}}